  for( int j=0; j<8; j++ ) { fd_ed25519_lane_recode16( dk[j], k[j] ); fd_ed25519_lane_recode256( ds[j], s[j] ); }
  struct { fd_ed25519_lane_point_t acc; fd_ed25519_lane_sel_t sel[2]; ulong const * src[8]; int neg[8]; } __attribute__((aligned(4096))) L;
  for( int i=0; i<5; i++ ) { L.acc.X.limb[i] = wwl_zero(); L.acc.Y.limb[i] = wwl_bcast( i==0 ); L.acc.Z.limb[i] = wwl_bcast( i==0 ); L.acc.T.limb[i] = wwl_zero(); }
