#define DIGITS_S( w ) for( int l=0; l<8; l++ ) { int d = ds[l][w], m = d>>31; L.neg[l] = m & 1; L.src[l] = fd_r52x5_lane_base_table[ (d ^ m) - m ]; }
  /* the entry of each addition is gathered during the addition before it */
  int cur = 0;
#define ADD( fn, stride ) do { fn##_pf( &L.acc.X, &L.acc.Y, &L.acc.Z, &L.acc.T, &L.acc.X, &L.acc.Y, &L.acc.Z, &L.acc.T, &L.sel[cur].YpX, &L.sel[cur].YmX, &L.sel[cur].T2d, L.src, L.neg, (stride), &L.sel[cur^1] ); cur ^= 1; } while(0)
#define ADD_NT( fn, stride ) do { fn##_pf( &L.acc.X, &L.acc.Y, &L.acc.Z, &L.acc.X, &L.acc.Y, &L.acc.Z, &L.acc.T, &L.sel[cur].YpX, &L.sel[cur].YmX, &L.sel[cur].T2d, L.src, L.neg, (stride), &L.sel[cur^1] ); cur ^= 1; } while(0)
