/* cnt <= 8 signatures as one lane group; results[j] is what fd_ed25519_verify returns for item
   j, including the order of the checks: S, A decodes, R decodes, A small order, R small order,
   the group equation */
void
fd_r52x5_lane_verify_x8( uchar const * const msgs[], ulong const msg_szs[], uchar const * const sigs[],
                           uchar const * const public_keys[], fd_sha512_t * shas[], int results[], ulong cnt ) {
  static uchar const identity_enc[ 32 ] = { 1 };  /* y = 1: the identity */
  uchar const * ea[8], * er[8];
  uchar k[8][32] = {{0}}, s[8][32] = {{0}};
  int cand = 0;
  for( ulong j=0; j<8UL; j++ ) {
    ea[j] = er[j] = identity_enc;
    if( j>=cnt ) continue;
    results[j] = FD_ED25519_ERR_SIG;
    if( FD_UNLIKELY( !fd_curve25519_scalar_validate( sigs[j]+32 ) ) ) continue;
    ea[j] = public_keys[j]; er[j] = sigs[j];
    cand |= 1<<j;
  }
  if( FD_UNLIKELY( !cand ) ) return;
  /* A decoded in lanes; R is checked by re-encoding the computed point: the canonical encoding
     equal to the signature's R means R decodes to that point (encodings of canonical form are
     unique). The lanes where it differs decode R afterwards, which also yields their codes. */
  fd_ed25519_lane_point_t A, R, Rc; int oka, okr;
  fd_ed25519_lane_decode_n( 1, &A, ea, &oka, &R, er, &okr );
  int sa = fd_ed25519_lane_small_order_mask( &A );
  int live = 0, slow = 0;  /* slow: lanes whose code needs R decoded (a small-order A: an R that does
                               not decode is reported first) */
  for( ulong j=0; j<cnt; j++ ) {
    int bit = 1<<j;
    if( !(cand & bit) ) continue;
    if( FD_UNLIKELY( !(oka & bit) ) ) results[j] = FD_ED25519_ERR_PUBKEY;
    else if( FD_UNLIKELY( sa & bit ) ) { results[j] = FD_ED25519_ERR_PUBKEY; slow |= bit; }
    else live |= bit;
  }
  if( FD_UNLIKELY( !live ) ) {
    if( FD_UNLIKELY( slow ) ) {
      fd_ed25519_lane_decode_n( 1, &R, er, &okr, &R, er, &okr );
      for( ulong j=0; j<cnt; j++ ) if( (slow & (1<<j)) && !(okr & (1<<j)) ) results[j] = FD_ED25519_ERR_SIG;
    }
    return;
  }
  /* k = SHA-512( R || A || msg ) mod L: the batched hash for messages that fit the copy buffer,
     the streaming one otherwise */
  uchar hash_input[8][64UL+FD_ED25519_LANE_HASH_COPY_MAX];
  uchar hashes[8][64];
  fd_sha512_batch_t batch[1];
  fd_sha512_batch_init( batch );
  for( ulong j=0; j<cnt; j++ ) {
    if( !(live & (1<<j)) ) continue;
    if( FD_LIKELY( msg_szs[j]<=FD_ED25519_LANE_HASH_COPY_MAX ) ) {
      fd_memcpy( hash_input[j], sigs[j], 32UL );
      fd_memcpy( hash_input[j]+32, public_keys[j], 32UL );
      if( msg_szs[j] ) fd_memcpy( hash_input[j]+64, msgs[j], msg_szs[j] );
      fd_sha512_batch_add( batch, hash_input[j], 64UL+msg_szs[j], hashes[j] );
    } else {
      fd_sha512_fini( fd_sha512_append( fd_sha512_append( fd_sha512_append( fd_sha512_init( shas[j] ),
                      sigs[j], 32UL ), public_keys[j], 32UL ), msgs[j], msg_szs[j] ), hashes[j] );
    }
  }
  fd_sha512_batch_fini( batch );
  for( ulong j=0; j<cnt; j++ ) {
    if( !(live & (1<<j)) ) continue;
    fd_curve25519_scalar_reduce( k[j], hashes[j] );
    fd_memcpy( s[j], sigs[j]+32, 32UL );
  }
  /* -A: negate X and T */
  fd_ed25519_lane_neg( &A.X, &A.X ); fd_ed25519_lane_neg( &A.T, &A.T );
  fd_r52x5_lane_double_scalar_mul( &Rc, (uchar const (*)[32])k, &A, (uchar const (*)[32])s );
  ulong cx[8][5], cy[8][5]; fd_ed25519_lane_affine_canon8( cx, cy, &Rc );
  for( ulong j=0; j<cnt; j++ ) {
    if( !(live & (1<<j)) ) continue;
    uchar enc[32]; fd_ed25519_lane_encode_canon( enc, cx[j], cy[j] );
    if( FD_LIKELY( fd_memeq( enc, sigs[j], 32UL ) ) ) {
      results[j] = fd_r52x5_affine_is_small_order( cx[j], cy[j] ) ? FD_ED25519_ERR_SIG : FD_ED25519_SUCCESS;
    } else slow |= 1<<j;
  }
  if( FD_LIKELY( !slow ) ) return;
  fd_ed25519_lane_decode_n( 1, &R, er, &okr, &R, er, &okr );
  int sr = fd_ed25519_lane_small_order_mask( &R );
  int eq = fd_ed25519_lane_eq_z1_mask( &Rc, &R );
  for( ulong j=0; j<cnt; j++ ) {
    int bit = 1<<j;
    if( !(slow & bit) ) continue;
    if( FD_UNLIKELY( !(okr & bit) ) ) results[j] = FD_ED25519_ERR_SIG;
    else if( sa & bit ) continue;  /* a small-order A with a decodable R: the code set above */
    else if( FD_UNLIKELY( sr & bit ) ) results[j] = FD_ED25519_ERR_SIG;
    else results[j] = (eq & bit) ? FD_ED25519_SUCCESS : FD_ED25519_ERR_MSG;
  }
}

void
fd_ed25519_verify_batch_multi_msg( uchar const * const msgs[],
                                   ulong const msg_szs[],
                                   uchar const * const sigs[],
                                   uchar const * const public_keys[],
                                   fd_sha512_t * shas[],
                                   int results[],
                                   ulong batch_sz ) {
  while( batch_sz ) {
    if( batch_sz<3UL ) {  /* too few for a lane group */
      for( ulong j=0; j<batch_sz; j++ ) results[j] = fd_ed25519_verify( msgs[j], msg_szs[j], sigs[j], public_keys[j], shas[j] );
      return;
    }
    ulong cnt = fd_ulong_min( batch_sz, 8UL );
    fd_r52x5_lane_verify_x8( msgs, msg_szs, sigs, public_keys, shas, results, cnt );
    msgs += cnt; msg_szs += cnt; sigs += cnt; public_keys += cnt; shas += cnt; results += cnt;
    batch_sz -= cnt;
  }
}

void
fd_ed25519_verify_batch_multi_msg_cached( uchar const * const msgs[],
                                          ulong const msg_szs[],
                                          uchar const * const sigs[],
                                          uchar const * const public_keys[],
                                          fd_sha512_t * shas[],
                                          int results[],
                                          ulong batch_sz,
                                          fd_ed25519_cache_t * cache ) {
  /* the tree's cache serves the small remainders; a lane group runs uncached */
  while( batch_sz ) {
    if( batch_sz<4UL ) {  /* too few for a lane group */
      for( ulong j=0; j<batch_sz; j++ ) results[j] = fd_ed25519_verify_cached( msgs[j], msg_szs[j], sigs[j], public_keys[j], shas[j], cache );
      return;
    }
    ulong cnt = fd_ulong_min( batch_sz, 8UL );
    fd_r52x5_lane_verify_x8( msgs, msg_szs, sigs, public_keys, shas, results, cnt );
    msgs += cnt; msg_szs += cnt; sigs += cnt; public_keys += cnt; shas += cnt; results += cnt;
    batch_sz -= cnt;
  }
}
